* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

:root {
  --bg: #ffffff;
  --surface: #ffffff;
  --surface-soft: #f7fafc;
  --border: #e6edf3;
  --border-strong: #d7e2ea;
  --text: #17202a;
  --text-soft: #5f6b76;
  --text-muted: #87939f;
  --blue: #2f6fb3;
  --cyan: #19a7b8;
  --blue-soft: #eaf4fb;
  --shadow:
    0 8px 24px
    rgba(26, 42, 58, 0.06);
  --radius-lg: 18px;
  --radius-md: 12px;
  --radius-sm: 8px;
}

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
  min-height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

button,
input,
select {
  font: inherit;
}

.mentions-page {
  width: 100%;
  min-height: 100%;
  padding: 24px;
  background: var(--bg);
}

/* HEADER */
.mentions-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 22px;
}

.mentions-header__text {
  min-width: 0;
}

.mentions-eyebrow {
  margin-bottom: 6px;
  color: var(--cyan);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.mentions-title {
  margin: 0;
  color: var(--text);
  font-size: 28px;
  font-weight: 700;
  line-height: 1.15;
}

.mentions-subtitle {
  margin: 8px 0 0;
  color: var(--text-soft);
  font-size: 14px;
  line-height: 1.5;
}

.mentions-header__meta {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
}

.query-badge,
.results-badge {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 7px 11px;
  border-radius: 999px;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 600;
}

.query-badge {
  border: 1px solid #cfe2f1;
  background: var(--blue-soft);
  color: var(--blue);
}

.results-badge {
  border: 1px solid var(--border);
  background: var(--surface-soft);
  color: var(--text-soft);
}

/* TOOLBAR */
.mentions-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.mentions-search {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 220px;
  height: 40px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  background: var(--surface);
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}

.mentions-search:focus-within {
  border-color: var(--cyan);
  box-shadow: 0 0 0 3px rgba(25, 167, 184, 0.1);
}

.mentions-search__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  flex: 0 0 40px;
  color: var(--text-muted);
  font-size: 18px;
}

.mentions-search__input {
  width: 100%;
  height: 100%;
  padding: 0 12px 0 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: 13px;
}

.mentions-search__input::placeholder {
  color: var(--text-muted);
}

.mentions-filters {
  display: flex;
  align-items: center;
  gap: 10px;
}

.mentions-select {
  min-width: 150px;
  height: 40px;
  padding: 0 34px 0 12px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  outline: 0;
  background: var(--surface);
  color: var(--text);
  font-size: 13px;
  cursor: pointer;
}

.mentions-select:focus {
  border-color: var(--cyan);
  box-shadow: 0 0 0 3px rgba(25, 167, 184, 0.1);
}

/* LIST */
.mentions-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.mention-card {
  position: relative;
  overflow: hidden;
  padding: 18px 18px 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: 0 4px 16px rgba(26, 42, 58, 0.035);
  transition: transform 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease;
}

.mention-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 3px;
  height: 100%;
  background: var(--cyan);
}

.mention-card:hover {
  transform: translateY(-1px);
  border-color: #cfdde7;
  box-shadow: 0 8px 22px rgba(26, 42, 58, 0.07);
}

.mention-card__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 8px;
}

.mention-card__source {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 8px;
}

.mention-card__source-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
  background: var(--cyan);
}

.mention-card__source-name {
  overflow: hidden;
  color: var(--text-soft);
  font-size: 12px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mention-card__date {
  flex: 0 0 auto;
  color: var(--text-muted);
  font-size: 11px;
  white-space: nowrap;
}

.mention-card__title {
  margin: 0 0 8px;
  color: var(--text);
  font-size: 15px;
  font-weight: 700;
  line-height: 1.4;
}

.mention-card__snippet {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.55;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.mention-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
}

.mention-card__keyword {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--surface-soft);
  color: var(--text-soft);
  font-size: 11px;
  font-weight: 600;
}

.mention-card__link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 0;
  background: transparent;
  color: var(--blue);
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
}

.mention-card__link:hover {
  text-decoration: underline;
}

/* STATES */
.mentions-state {
  display: flex;
  min-height: 260px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  padding: 32px;
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-lg);
  background: var(--surface-soft);
  text-align: center;
}

.mentions-state__icon {
  margin-bottom: 12px;
  color: var(--cyan);
  font-size: 34px;
}

.mentions-state__title {
  color: var(--text);
  font-size: 15px;
  font-weight: 700;
}

.mentions-state__text {
  max-width: 420px;
  margin-top: 6px;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.5;
}

.mentions-state__spinner {
  width: 28px;
  height: 28px;
  margin-bottom: 14px;
  border: 3px solid #dce8ee;
  border-top-color: var(--cyan);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
/* RESPONSIVE */
@media (max-width: 820px) {
  .mentions-page {
    padding: 18px;
  }
  .mentions-header {
    flex-direction: column;
  }
  .mentions-header__meta {
    justify-content: flex-start;
  }
  .mentions-toolbar {
    align-items: stretch;
    flex-direction: column;
  }
  .mentions-filters {
    width: 100%;
  }
  .mentions-select {
    flex: 1;
    min-width: 0;
  }
}
@media (max-width: 560px) {
  .mentions-filters {
    flex-direction: column;
  }
  .mentions-select {
    width: 100%;
  }
  .mention-card__top,
  .mention-card__footer {
    align-items: flex-start;
    flex-direction: column;
  }
  .mention-card__date {
    white-space: normal;
  }
}

