let state = {
  search: '',
  source: '',
  sort: 'newest'
};
let initialized = false;
function getModel() {
  return appsmith.model || {};
}
function getMentions() {
  const model = getModel();
  return Array.isArray(model.mentions) ? model.mentions : [];
}
function normalize(value) {
  return String(value || '').normalize('NFC').toLocaleLowerCase('es').replace(/\s+/g, ' ').trim();
}
function formatDate(value) {
  if (!value) {
    return 'Sin fecha';
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return 'Sin fecha';
  }
  return new Intl.DateTimeFormat('es-MX', {
    timeZone: 'America/Mexico_City',
    year: 'numeric',
    month: 'short',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit'
  }).format(date);
}
function getMentionDate(mention) {
  const value = mention.published_at || mention.detected_at || '';
  const timestamp = new Date(value).getTime();
  return Number.isNaN(timestamp) ? 0 : timestamp;
}
function getFilteredMentions() {
  let mentions = [...getMentions()];
  const search = normalize(state.search);
  if (search) {
    mentions = mentions.filter(function (mention) {
      const searchable = normalize([mention.title, mention.snippet, mention.source_name, mention.source_domain, mention.phrase].join(' '));
      return searchable.includes(search);
    });
  }
  if (state.source) {
    mentions = mentions.filter(function (mention) {
      return String(mention.source_domain || mention.source_name || '') === state.source;
    });
  }
  mentions.sort(function (a, b) {
    const dateA = getMentionDate(a);
    const dateB = getMentionDate(b);
    return state.sort === 'oldest' ? dateA - dateB : dateB - dateA;
  });
  return mentions;
}
function createTextElement(tag, className, text) {
  const element = document.createElement(tag);
  element.className = className;
  element.textContent = String(text || '');
  return element;
}
function createMentionCard(mention) {
  const card = document.createElement('article');
  card.className = 'mention-card';
  const top = document.createElement('div');
  top.className = 'mention-card__top';
  const source = document.createElement('div');
  source.className = 'mention-card__source';
  const dot = document.createElement('span');
  dot.className = 'mention-card__source-dot';
  const sourceName = createTextElement('span', 'mention-card__source-name', mention.source_domain || mention.source_name || 'Fuente desconocida');
  source.append(dot, sourceName);
  const date = createTextElement('div', 'mention-card__date', formatDate(mention.published_at || mention.detected_at));
  top.append(source, date);
  const title = createTextElement('h2', 'mention-card__title', mention.title || 'Sin título');
  const snippet = createTextElement('p', 'mention-card__snippet', mention.snippet || 'Sin descripción disponible.');
  const footer = document.createElement('div');
  footer.className = 'mention-card__footer';
  const keyword = createTextElement('span', 'mention-card__keyword', mention.phrase || 'Sin keyword');
  footer.appendChild(keyword);
  const sourceUrl = String(mention.source_url || '').trim();
  if (/^https?:\/\//i.test(sourceUrl)) {
    const link = document.createElement('a');
    link.className = 'mention-card__link';
    link.href = sourceUrl;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.textContent = 'Abrir fuente ↗';
    footer.appendChild(link);
  }
  card.append(top, title, snippet, footer);
  return card;
}
function updateSourceFilter() {
  const select = document.getElementById('sourceFilter');
  if (!select) {
    return;
  }
  const previousValue = state.source;
  const sources = [...new Set(getMentions().map(function (mention) {
    return String(mention.source_domain || mention.source_name || '').trim();
  }).filter(Boolean))].sort(function (a, b) {
    return a.localeCompare(b, 'es');
  });
  select.replaceChildren();
  const allOption = document.createElement('option');
  allOption.value = '';
  allOption.textContent = 'Todas las fuentes';
  select.appendChild(allOption);
  for (const source of sources) {
    const option = document.createElement('option');
    option.value = source;
    option.textContent = source;
    select.appendChild(option);
  }
  if (previousValue && sources.includes(previousValue)) {
    select.value = previousValue;
  } else {
    state.source = '';
    select.value = '';
  }
}
function render() {
  const model = getModel();
  const queryBadge = document.getElementById('queryBadge');
  const resultsBadge = document.getElementById('resultsBadge');
  const loadingState = document.getElementById('loadingState');
  const emptyState = document.getElementById('emptyState');
  const mentionsList = document.getElementById('mentionsList');
  if (!queryBadge || !resultsBadge || !loadingState || !emptyState || !mentionsList) {
    return;
  }
  queryBadge.textContent = model.activeQueryName || 'Sin consulta activa';
  updateSourceFilter();
  const filteredMentions = getFilteredMentions();
  const totalMentions = getMentions().length;
  resultsBadge.textContent = filteredMentions.length === totalMentions ? `${totalMentions} ${totalMentions === 1 ? 'mención' : 'menciones'}` : `${filteredMentions.length} de ${totalMentions}`;
  mentionsList.replaceChildren();
  const isLoading = Boolean(model.isLoading);
  loadingState.hidden = !isLoading;
  if (isLoading) {
    emptyState.hidden = true;
    mentionsList.hidden = true;
    return;
  }
  mentionsList.hidden = false;
  if (!model.activeQueryId || totalMentions === 0) {
    emptyState.hidden = false;
    return;
  }
  if (filteredMentions.length === 0) {
    emptyState.hidden = false;
    const title = emptyState.querySelector('.mentions-state__title');
    const text = emptyState.querySelector('.mentions-state__text');
    if (title) {
      title.textContent = 'No hay coincidencias';
    }
    if (text) {
      text.textContent = 'No encontramos menciones con los filtros seleccionados.';
    }
    return;
  }
  emptyState.hidden = true;
  for (const mention of filteredMentions) {
    mentionsList.appendChild(createMentionCard(mention));
  }
}
function bindEvents() {
  const searchInput = document.getElementById('searchInput');
  const sourceFilter = document.getElementById('sourceFilter');
  const sortFilter = document.getElementById('sortFilter');
  if (searchInput) {
    searchInput.addEventListener('input', function (event) {
      state.search = event.target.value || '';
      render();
    });
  }
  if (sourceFilter) {
    sourceFilter.addEventListener('change', function (event) {
      state.source = event.target.value || '';
      render();
    });
  }
  if (sortFilter) {
    sortFilter.addEventListener('change', function (event) {
      state.sort = event.target.value || 'newest';
      render();
    });
  }
}
function initialize() {
  if (initialized) {
    return;
  }
  initialized = true;
  bindEvents();
  render();
  appsmith.onModelChange(function () {
    render();
  });
}
appsmith.onReady(function () {
  initialize();
});

